  if (gapPx > 118) {
    txt(gLeft, 'u = u\u2080', LF.fx(uA), topY, { size: 18 });
    txt(gLeft, 'u = u\u2080 + \u0394u', Math.min(LF.fx(uB) + 34, LP.x + LP.w - 76), topY, { size: 18 });
  } else {
    txt(gLeft, 'u = u\u2080', LF.fx(uA) - 14, topY, { size: 18 });
    txt(gLeft, 'u = u\u2080 + \u0394u', Math.min(LF.fx(uB) + 52, LP.x + LP.w - 76), topY - 26, { size: 18 });
  }

  var xEnd = LF.fx(uB + ext) + 10;
  var yA = LF.fy(vA), yB2 = LF.fy(vB);
  if (yA - yB2 < 28) { var mid = (yA + yB2) / 2; yA = mid + 15; yB2 = mid - 15; }
  txt(gLeft, 'v = v\u2080', Math.min(xEnd, LP.x + LP.w - 92), yA, { size: 18, anchor: 'start' });
  txt(gLeft, 'v = v\u2080 + \u0394v', Math.min(xEnd, LP.x + LP.w - 136), yB2, { size: 18, anchor: 'start' });

  txt(gLeft, '\u0394u', LF.fx(uA + d / 2), LF.fy(vA) + 22, { size: 18 });
  txt(gLeft, '\u0394v', LF.fx(uB) + 14, LF.fy(vA + d / 2), { size: 18, anchor: 'start' });
  txt(gLeft, '(u\u2080, v\u2080)', Math.max(LF.fx(uA) - 12, LP.x + 66), LF.fy(vA) + 28, { size: 18, anchor: 'end' });
  txt(gLeft, 'S', LF.fx(uA + d / 2), LF.fy(vA + d / 2), { size: 22 });
}

/* ---------- numerics ---------- */
function jac(u, v) {
  var h = 1e-4;
  var xu = (fxF(u + h, v) - fxF(u - h, v)) / (2 * h);
  var xv = (fxF(u, v + h) - fxF(u, v - h)) / (2 * h);
  var yu = (fyF(u + h, v) - fyF(u - h, v)) / (2 * h);
  var yv = (fyF(u, v + h) - fyF(u, v - h)) / (2 * h);
  return { xu: xu, xv: xv, yu: yu, yv: yv, det: xu * yv - xv * yu };
}
function shoelace(poly) {
  var a = 0;
  for (var i = 0; i < poly.length; i++) {
    var p = poly[i], q = poly[(i + 1) % poly.length];
    a += p[0] * q[1] - q[0] * p[1];
  }
  return Math.abs(a) / 2;
}

/* ---------- right panel ---------- */
var lastStats = { areaS: 0, areaR: 0, det: 0 };

function drawRightPanel() {
  var u0 = st.u0, v0 = st.v0, d = st.d, ext = Math.max(0.35 * d, 0.24);
  var N = 44;
  function pt(u, v) {
    var X = fxF(u, v), Y = fyF(u, v);
    return (isFinite(X) && isFinite(Y)) ? [X, Y] : null;
  }
  function curve(kind, fixed, a, b) {
    var out = [];
    for (var i = 0; i <= N; i++) {
      var t = a + (b - a) * i / N;
      var p = (kind === 'u') ? pt(fixed, t) : pt(t, fixed);
      if (p) out.push(p);
    }
    return out;
  }
  var cU0 = curve('u', u0, v0 - ext, v0 + d + ext);
  var cU1 = curve('u', u0 + d, v0 - ext, v0 + d + ext);
  var cV0 = curve('v', v0, u0 - ext, u0 + d + ext);
  var cV1 = curve('v', v0 + d, u0 - ext, u0 + d + ext);
  var bnd = curve('v', v0, u0, u0 + d)
    .concat(curve('u', u0 + d, v0, v0 + d))
    .concat(curve('v', v0 + d, u0 + d, u0))
    .concat(curve('u', u0, v0 + d, v0));

  var all = cU0.concat(cU1, cV0, cV1, bnd, [[0, 0]]);
  if (all.length < 3) return;
  var x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  all.forEach(function (p) {
    if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
    if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
  });
  var spx = Math.max(x1 - x0, 0.5), spy = Math.max(y1 - y0, 0.5);
  x0 -= 0.1 * spx; x1 += 0.12 * spx; y0 -= 0.1 * spy; y1 += 0.12 * spy;
  var RF = fit(RP, [x0, x1], [y0, y1]);

  drawAxes(gRight, RF, 'x', 'y');

  // region R
  var scr = bnd.map(function (p) { return [RF.fx(p[0]), RF.fy(p[1])]; });
  if (scr.length > 3) {
    var poly = gRight.polygon(pts2str(scr)).fill(FILLC).stroke({ color: EDGE, width: 1 });
    poly.css('cursor', 'pointer');
    poly.on('mousemove', function (e) { showTooltip('R = T(S): area ≈ |J|·Δu·Δv', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The image region R', 'R is the curved image of the rectangle S. Its area is no longer Δu·Δv — it is roughly |∂(x,y)/∂(u,v)| times that, evaluated near (u₀, v₀). That factor is exactly what appears in the change-of-variables formula.');
      });
  }
  var cx = 0, cy = 0;
  bnd.forEach(function (p) { cx += p[0]; cy += p[1]; });
  cx /= bnd.length; cy /= bnd.length;
  var cX = RF.fx(cx), cY = RF.fy(cy);

  // four image curves
  function drawCurve(c) {
    if (c.length < 2) return;
    gRight.polyline(pts2str(c.map(function (p) { return [RF.fx(p[0]), RF.fy(p[1])]; })))
      .fill('none').stroke({ color: BLUE, width: 3.2, linecap: 'round', linejoin: 'round' });
  }
  [cU0, cU1, cV0, cV1].forEach(drawCurve);

  // image corners
  [[u0, v0], [u0 + d, v0], [u0, v0 + d], [u0 + d, v0 + d]].forEach(function (c) {
    var p = pt(c[0], c[1]);
    if (p) gRight.circle(11).center(RF.fx(p[0]), RF.fy(p[1])).fill(EDGE);
  });

  txt(gRight, 'R', cX, cY, { size: 22 });

  // curve labels at the free ends
  function endLabel(c, s) {
    if (!c.length) return;
    var p = c[c.length - 1];
    var px = RF.fx(p[0]), py = RF.fy(p[1]);
    var dirX = (px < cX) ? -1 : 1, dirY = (py < cY) ? -1 : 1;
    var size = 15, w = 0.47 * size * s.length;
    var anchor = dirX > 0 ? 'start' : 'end';
    var lx = px + dirX * 12, ly = py + dirY * 15;
    if (anchor === 'start' && lx + w > RP.x + RP.w - 2) { anchor = 'end'; lx = px - 12; }
    if (anchor === 'end' && lx - w < RP.x + 2) { anchor = 'start'; lx = Math.max(px + 12, RP.x + 2); }
    ly = clamp(ly, RP.y + 12, RP.y + RP.h - 10);
    txt(gRight, s, lx, ly, { size: size, anchor: anchor, halo: 4 });
  }
  endLabel(cU0, 'Image of u = u\u2080');
  endLabel(cU1, 'Image of u = u\u2080 + \u0394u');
  endLabel(cV0, 'Image of v = v\u2080');
  endLabel(cV1, 'Image of v = v\u2080 + \u0394v');

  // stats
  var J = jac(u0, v0);
  lastStats = { areaS: d * d, areaR: shoelace(bnd), det: J.det };

  // tangent-vector overlay
  if (st.showJ) {
    var P = pt(u0, v0);
    if (P) {
      var Pu = [P[0] + J.xu * d, P[1] + J.yu * d];
      var Pv = [P[0] + J.xv * d, P[1] + J.yv * d];
      var Puv = [P[0] + (J.xu + J.xv) * d, P[1] + (J.yu + J.yv) * d];
      var S = function (p) { return [RF.fx(p[0]), RF.fy(p[1])]; };
      gRight.polygon(pts2str([S(P), S(Pu), S(Puv), S(Pv)]))
        .fill('none').stroke({ color: ORANGE, width: 2, dasharray: '7,5', linejoin: 'round' });
      function arrow(a, b, lab) {
        var A = S(a), B = S(b);
        var vx = B[0] - A[0], vy = B[1] - A[1], L = Math.hypot(vx, vy) || 1;
        var ux = vx / L, uy = vy / L, hl = Math.min(14, L * 0.3);
        gRight.line(A[0], A[1], B[0] - ux * hl * 0.85, B[1] - uy * hl * 0.85)
          .stroke({ color: ORANGE, width: 3, linecap: 'round' });
        gRight.polygon([[B[0], B[1]],
        [B[0] - ux * hl - uy * hl * 0.42, B[1] - uy * hl + ux * hl * 0.42],
        [B[0] - ux * hl + uy * hl * 0.42, B[1] - uy * hl - ux * hl * 0.42]]).fill(ORANGE);
        txt(gRight, lab, clamp(B[0] + ux * 16, RP.x + 26, RP.x + RP.w - 26),
          clamp(B[1] + uy * 16, RP.y + 12, RP.y + RP.h - 10),
          { size: 14, fill: ORANGE, halo: 4 });
      }
      arrow(P, Pu, 'T\u1D64 \u0394u');
      arrow(P, Pv, 'T\u1D65 \u0394v');
    }

    // readout box in the gap, below the arrow
    var bx = 498, by = 326, bw = 196, bh = 92;
    gInfo.rect(bw, bh).move(bx, by).fill('#ffffff').opacity(0.94)
      .stroke({ color: '#bbb', width: 1 }).radius(5);
    var lines = [
      '\u0394u = \u0394v = ' + st.d.toFixed(2),
      'area(S) = \u0394u\u0394v = ' + lastStats.areaS.toFixed(4),
      'area(R) = ' + lastStats.areaR.toFixed(4),
      'area(R)/area(S) = ' + (lastStats.areaS ? (lastStats.areaR / lastStats.areaS).toFixed(4) : '—'),
      '|J| at (u\u2080,v\u2080) = ' + Math.abs(lastStats.det).toFixed(4)
    ];
    lines.forEach(function (s, i) {
      txt(gInfo, s, bx + 10, by + 15 + i * 17,
        { size: 12.5, anchor: 'start', italic: false, family: 'sans-serif', halo: false });
    });
  }
}

/* ---------- master redraw ---------- */
function redraw() {
  if (!fxF || !fyF) return;
  gLeft.clear(); gRight.clear(); gInfo.clear();
  drawLeftPanel();
  drawRightPanel();
  updateReadout();
}
function updateReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  var ratio = lastStats.areaS ? (lastStats.areaR / lastStats.areaS) : 0;
  el.textContent =
    '(u\u2080, v\u2080) = (' + st.u0.toFixed(2) + ', ' + st.v0.toFixed(2) + ')\n' +
    '\u0394u = \u0394v = ' + st.d.toFixed(2) + '\n' +
    'area(S)  = ' + lastStats.areaS.toFixed(4) + '\n' +
    'area(R)  = ' + lastStats.areaR.toFixed(4) + '\n' +
    'ratio    = ' + ratio.toFixed(4) + '\n' +
    '|J|      = ' + Math.abs(lastStats.det).toFixed(4);
}

/* ---------- dragging ---------- */
var dragMode = null;
function clientToVB(e) {
  var r = draw.node.getBoundingClientRect();
  var s = Math.min(r.width / VW, r.height / VH);
  var ox = (r.width - VW * s) / 2, oy = (r.height - VH * s) / 2;
  return { x: (e.clientX - r.left - ox) / s, y: (e.clientY - r.top - oy) / s };
}
window.addEventListener('mousemove', function (e) {
  if (!dragMode) return;
  var p = clientToVB(e);
  var u = LF.ix(p.x), v = LF.iy(p.y);
  if (dragMode === 'move') {
    st.u0 = clamp(u, 0.15, 3.4 - st.d);
    st.v0 = clamp(v, 0.10, 2.3 - st.d);
  } else {
    var nd = Math.max(u - st.u0, v - st.v0);
    nd = clamp(Math.round(nd / 0.05) * 0.05, 0.05, 1.2);
    nd = Math.min(nd, 3.4 - st.u0, 2.3 - st.v0);
    st.d = nd;
    var si = document.getElementById('shrinkInput');
    if (si) { si.value = String(st.d); document.getElementById('shrinkVal').value = st.d.toFixed(2); }
  }
  redraw();
});
window.addEventListener('mouseup', function () { dragMode = null; });

/* ---------- controls ---------- */
function update_shrink(v) {
  st.d = clamp(v, 0.05, 1.2);
  st.u0 = Math.min(st.u0, 3.4 - st.d);
  st.v0 = Math.min(st.v0, 2.3 - st.d);
  redraw();
}
function toggle_showJacobian(on) { st.showJ = !!on; redraw(); }
window.update_shrink = update_shrink;
window.toggle_showJacobian = toggle_showJacobian;

/* ---------- equation inputs ---------- */
var bindX = bindEquationInput('xuvInput', function (fn) { fxF = fn; redraw(); }, { variables: ['u', 'v'] });
var bindY = bindEquationInput('yuvInput', function (fn) { fyF = fn; redraw(); }, { variables: ['u', 'v'] });

function setPreset(xs, ys) {
  document.getElementById('xuvInput').value = xs; bindX.apply(xs);
  document.getElementById('yuvInput').value = ys; bindY.apply(ys);
}
window.setPreset = setPreset;

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'A rectangle and its image',
    narration: 'The pale rectangle S in the uv-plane is built from two u-lines and two v-lines. Under T(u,v) = (u cos v, u sin v) those four straight lines become four curves, and S becomes the curved region R.',
    state: { shrink: 0.8, showJ: false, x: 'u*cos(v)', y: 'u*sin(v)', u0: 1.30, v0: 0.15 }
  },
  {
    title: 'Which curve came from which line',
    narration: 'Each edge keeps its identity: the line u = u₀ maps to a circular arc, the line v = v₀ maps to a ray. Drag a corner of S and watch every image curve follow.',
    state: { shrink: 0.8, showJ: false, x: 'u*cos(v)', y: 'u*sin(v)', u0: 1.70, v0: 0.35 }
  },
  {
    title: 'The Jacobian as a stretch factor',
    narration: 'Turn on the tangent vectors. The parallelogram they span hugs R, and its area is |∂(x,y)/∂(u,v)| times the area ΔuΔv of S.',
    state: { shrink: 0.8, showJ: true, x: 'u*cos(v)', y: 'u*sin(v)', u0: 1.70, v0: 0.35 }
  },
  {
    title: 'Shrink the cell',
    narration: 'Reduce Δu and Δv. The curved sides flatten, R becomes indistinguishable from the parallelogram, and the ratio area(R)/area(S) locks onto the Jacobian value at (u₀, v₀).',
    state: { shrink: 0.1, showJ: true, x: 'u*cos(v)', y: 'u*sin(v)', u0: 1.70, v0: 0.35 }
  },
  {
    title: 'Change the map',
    narration: 'Edit x(u,v) and y(u,v) — here x = u² − v², y = 2uv. The rectangle never moves, but R and the local stretch factor change completely.',
    state: { shrink: 0.4, showJ: true, x: 'u^2 - v^2', y: '2*u*v', u0: 1.30, v0: 0.40 }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx], S = s.state;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + '/' + steps.length + ': ' + s.title;
  st.u0 = S.u0; st.v0 = S.v0;
  var si = document.getElementById('shrinkInput');
  si.value = String(S.shrink);
  document.getElementById('shrinkVal').value = String(S.shrink);
  st.d = S.shrink;
  var cb = document.getElementById('showJacobianInput');
  cb.checked = !!S.showJ; st.showJ = !!S.showJ;
  setPreset(S.x, S.y);
  redraw();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }
window.nextStep = nextStep; window.prevStep = prevStep;

applyStep(0);
redraw();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A change of variables T(u,v) = (x(u,v), y(u,v)) maps a small rectangle S in the uv-plane to a curved region R in the xy-plane, and the Jacobian determinant is the local factor by which that map stretches area.
KEY INSIGHT (what students should walk away understanding): dA in the xy-plane is not du dv: a change of variables bends a rectangle into a curved patch whose area is |∂(x,y)/∂(u,v)| du dv, and that Jacobian factor is just the local area-stretch of the map.
DEMO STEPS: 5 guided steps — implement the step player in #ui

